FILES = {'settings.gradle': "pluginManagement {\n    repositories { google(); mavenCentral(); gradlePluginPortal() }\n}\ndependencyResolutionManagement {\n    repositories { google(); mavenCentral() }\n}\nrootProject.name = 'GrokBear'\ninclude ':app'\n", 'build.gradle': "plugins {\n    id 'com.android.application' version '8.5.2' apply false\n}\n", 'gradle.properties': 'org.gradle.jvmargs=-Xmx2g\nandroid.useAndroidX=false\n', 'app/build.gradle': "plugins { id 'com.android.application' }\n\nandroid {\n    namespace 'com.grokbear'\n    compileSdk 34\n    defaultConfig {\n        applicationId 'com.grokbear'\n        minSdk 30\n        targetSdk 34\n        versionCode 1\n        versionName '1.0'\n    }\n    compileOptions {\n        sourceCompatibility JavaVersion.VERSION_17\n        targetCompatibility JavaVersion.VERSION_17\n    }\n}\n", 'app/src/main/AndroidManifest.xml': '<?xml version="1.0" encoding="utf-8"?>\n<manifest xmlns:android="http://schemas.android.com/apk/res/android">\n    <uses-permission android:name="android.permission.INTERNET"/>\n    <application\n        android:label="@string/app_name"\n        android:icon="@android:drawable/sym_def_app_icon"\n        android:theme="@android:style/Theme.Material.Light">\n        <activity android:name=".MainActivity" android:exported="true">\n            <intent-filter>\n                <action android:name="android.intent.action.MAIN"/>\n                <category android:name="android.intent.category.LAUNCHER"/>\n            </intent-filter>\n        </activity>\n        <service\n            android:name=".BearService"\n            android:exported="true"\n            android:label="@string/app_name"\n            android:permission="android.permission.BIND_ACCESSIBILITY_SERVICE">\n            <intent-filter>\n                <action android:name="android.accessibilityservice.AccessibilityService"/>\n            </intent-filter>\n            <meta-data\n                android:name="android.accessibilityservice"\n                android:resource="@xml/accessibility_config"/>\n        </service>\n    </application>\n</manifest>\n', 'app/src/main/res/values/strings.xml': '<?xml version="1.0" encoding="utf-8"?>\n<resources>\n    <string name="app_name">Grok Мишка</string>\n    <string name="desc">Плавающая кнопка-мишка: делает скриншот экрана и присылает ответ от Grok.</string>\n</resources>\n', 'app/src/main/res/xml/accessibility_config.xml': '<?xml version="1.0" encoding="utf-8"?>\n<accessibility-service xmlns:android="http://schemas.android.com/apk/res/android"\n    android:accessibilityEventTypes="typeWindowStateChanged"\n    android:accessibilityFeedbackType="feedbackGeneric"\n    android:accessibilityFlags="flagDefault"\n    android:canTakeScreenshot="true"\n    android:notificationTimeout="100"\n    android:description="@string/desc"/>\n', 'app/src/main/java/com/grokbear/MainActivity.java': 'package com.grokbear;\n\nimport android.app.Activity;\nimport android.content.Intent;\nimport android.content.SharedPreferences;\nimport android.os.Bundle;\nimport android.provider.Settings;\nimport android.text.InputType;\nimport android.view.View;\nimport android.widget.*;\n\npublic class MainActivity extends Activity {\n    @Override\n    protected void onCreate(Bundle b) {\n        super.onCreate(b);\n        final SharedPreferences sp = getSharedPreferences("p", MODE_PRIVATE);\n        int pad = (int) (16 * getResources().getDisplayMetrics().density);\n\n        ScrollView sv = new ScrollView(this);\n        LinearLayout root = new LinearLayout(this);\n        root.setOrientation(LinearLayout.VERTICAL);\n        root.setPadding(pad, pad, pad, pad);\n        sv.addView(root);\n\n        TextView title = new TextView(this);\n        title.setText("\\uD83D\\uDC3B Grok Мишка");\n        title.setTextSize(26);\n        root.addView(title);\n\n        TextView info = new TextView(this);\n        info.setText("1) Вставь API-ключ xAI и нажми Сохранить.\\n"\n                + "2) Нажми «Включить мишку» -> найди «Grok Мишка» -> включи.\\n"\n                + "3) Поверх любых приложений появится \\uD83D\\uDC3B. Нажми на него - получишь ответ по экрану. Можно перетаскивать.");\n        info.setPadding(0, pad, 0, pad);\n        root.addView(info);\n\n        final EditText key = new EditText(this);\n        key.setHint("API-ключ xAI (xai-...)");\n        key.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_PASSWORD);\n        key.setText(sp.getString("key", ""));\n        root.addView(key);\n\n        final EditText model = new EditText(this);\n        model.setHint("Модель (например grok-4)");\n        model.setText(sp.getString("model", "grok-4"));\n        root.addView(model);\n\n        Button save = new Button(this);\n        save.setText("Сохранить");\n        save.setOnClickListener(new View.OnClickListener() {\n            public void onClick(View v) {\n                sp.edit().putString("key", key.getText().toString().trim())\n                        .putString("model", model.getText().toString().trim()).apply();\n                Toast.makeText(MainActivity.this, "Сохранено", Toast.LENGTH_SHORT).show();\n            }\n        });\n        root.addView(save);\n\n        Button en = new Button(this);\n        en.setText("Включить мишку (спецвозможности)");\n        en.setOnClickListener(new View.OnClickListener() {\n            public void onClick(View v) {\n                startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS));\n            }\n        });\n        root.addView(en);\n\n        setContentView(sv);\n    }\n}\n', 'app/src/main/java/com/grokbear/BearService.java': 'package com.grokbear;\n\nimport android.accessibilityservice.AccessibilityService;\nimport android.content.Intent;\nimport android.content.SharedPreferences;\nimport android.graphics.Bitmap;\nimport android.graphics.Color;\nimport android.graphics.PixelFormat;\nimport android.graphics.drawable.GradientDrawable;\nimport android.os.Handler;\nimport android.os.Looper;\nimport android.util.Base64;\nimport android.util.DisplayMetrics;\nimport android.view.Display;\nimport android.view.Gravity;\nimport android.view.MotionEvent;\nimport android.view.View;\nimport android.view.WindowManager;\nimport android.view.accessibility.AccessibilityEvent;\nimport android.widget.*;\n\nimport org.json.JSONArray;\nimport org.json.JSONObject;\n\nimport java.io.ByteArrayOutputStream;\nimport java.io.InputStream;\nimport java.io.OutputStream;\nimport java.net.HttpURLConnection;\nimport java.net.URL;\n\npublic class BearService extends AccessibilityService {\n    private WindowManager wm;\n    private TextView bear;\n    private LinearLayout panel;\n    private TextView answer;\n    private WindowManager.LayoutParams bearLp;\n    private final Handler ui = new Handler(Looper.getMainLooper());\n    private boolean busy = false;\n\n    @Override\n    protected void onServiceConnected() {\n        wm = (WindowManager) getSystemService(WINDOW_SERVICE);\n        addBear();\n        addPanel();\n    }\n\n    @Override public void onAccessibilityEvent(AccessibilityEvent e) {}\n    @Override public void onInterrupt() {}\n\n    @Override\n    public boolean onUnbind(Intent i) {\n        try { if (bear != null) wm.removeView(bear); } catch (Exception ignored) {}\n        try { if (panel != null) wm.removeView(panel); } catch (Exception ignored) {}\n        return super.onUnbind(i);\n    }\n\n    private int dp(int v) {\n        return (int) (v * getResources().getDisplayMetrics().density);\n    }\n\n    private void addBear() {\n        bear = new TextView(this);\n        bear.setText("\\uD83D\\uDC3B");\n        bear.setTextSize(30);\n        bear.setGravity(Gravity.CENTER);\n        GradientDrawable bg = new GradientDrawable();\n        bg.setShape(GradientDrawable.OVAL);\n        bg.setColor(Color.parseColor("#CC222222"));\n        bear.setBackground(bg);\n\n        bearLp = new WindowManager.LayoutParams(dp(64), dp(64),\n                WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,\n                WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,\n                PixelFormat.TRANSLUCENT);\n        bearLp.gravity = Gravity.TOP | Gravity.START;\n        bearLp.x = dp(8);\n        bearLp.y = dp(160);\n\n        bear.setOnTouchListener(new View.OnTouchListener() {\n            int sx, sy; float tx, ty; boolean moved;\n            public boolean onTouch(View v, MotionEvent e) {\n                switch (e.getAction()) {\n                    case MotionEvent.ACTION_DOWN:\n                        sx = bearLp.x; sy = bearLp.y; tx = e.getRawX(); ty = e.getRawY(); moved = false;\n                        return true;\n                    case MotionEvent.ACTION_MOVE:\n                        float dx = e.getRawX() - tx, dy = e.getRawY() - ty;\n                        if (Math.abs(dx) > 12 || Math.abs(dy) > 12) moved = true;\n                        if (moved) {\n                            bearLp.x = sx + (int) dx; bearLp.y = sy + (int) dy;\n                            wm.updateViewLayout(bear, bearLp);\n                        }\n                        return true;\n                    case MotionEvent.ACTION_UP:\n                        if (!moved) onBearClick();\n                        return true;\n                }\n                return false;\n            }\n        });\n        wm.addView(bear, bearLp);\n    }\n\n    private void addPanel() {\n        panel = new LinearLayout(this);\n        panel.setOrientation(LinearLayout.VERTICAL);\n        panel.setBackgroundColor(Color.parseColor("#F2202020"));\n        panel.setPadding(dp(12), dp(12), dp(12), dp(12));\n\n        ScrollView sv = new ScrollView(this);\n        answer = new TextView(this);\n        answer.setTextColor(Color.WHITE);\n        answer.setTextSize(16);\n        answer.setTextIsSelectable(true);\n        sv.addView(answer);\n        DisplayMetrics dm = getResources().getDisplayMetrics();\n        panel.addView(sv, new LinearLayout.LayoutParams(\n                LinearLayout.LayoutParams.MATCH_PARENT, (int) (dm.heightPixels * 0.4)));\n\n        Button close = new Button(this);\n        close.setText("Закрыть");\n        close.setOnClickListener(new View.OnClickListener() {\n            public void onClick(View v) { panel.setVisibility(View.GONE); }\n        });\n        panel.addView(close);\n        panel.setVisibility(View.GONE);\n\n        WindowManager.LayoutParams lp = new WindowManager.LayoutParams(\n                WindowManager.LayoutParams.MATCH_PARENT, WindowManager.LayoutParams.WRAP_CONTENT,\n                WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,\n                WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,\n                PixelFormat.TRANSLUCENT);\n        lp.gravity = Gravity.BOTTOM;\n        wm.addView(panel, lp);\n    }\n\n    private void showText(String t) {\n        answer.setText(t);\n        panel.setVisibility(View.VISIBLE);\n    }\n\n    private void onBearClick() {\n        if (busy) return;\n        SharedPreferences sp = getSharedPreferences("p", MODE_PRIVATE);\n        if (sp.getString("key", "").isEmpty()) {\n            showText("Сначала открой приложение «Grok Мишка» и вставь API-ключ.");\n            return;\n        }\n        busy = true;\n        bear.setVisibility(View.INVISIBLE);\n        panel.setVisibility(View.GONE);\n        ui.postDelayed(new Runnable() {\n            public void run() { capture(); }\n        }, 300);\n    }\n\n    private void capture() {\n        takeScreenshot(Display.DEFAULT_DISPLAY, getMainExecutor(), new TakeScreenshotCallback() {\n            @Override\n            public void onSuccess(ScreenshotResult r) {\n                Bitmap hw = Bitmap.wrapHardwareBuffer(r.getHardwareBuffer(), r.getColorSpace());\n                Bitmap bmp = hw.copy(Bitmap.Config.ARGB_8888, false);\n                r.getHardwareBuffer().close();\n                bear.setVisibility(View.VISIBLE);\n                showText("\\uD83D\\uDC3B Думаю...");\n                final Bitmap fb = bmp;\n                new Thread(new Runnable() {\n                    public void run() { ask(fb); }\n                }).start();\n            }\n\n            @Override\n            public void onFailure(int code) {\n                busy = false;\n                bear.setVisibility(View.VISIBLE);\n                showText("Не удалось сделать скриншот (код " + code + "). Подожди секунду и нажми ещё раз.");\n            }\n        });\n    }\n\n    private void ask(Bitmap bmp) {\n        String result;\n        try {\n            SharedPreferences sp = getSharedPreferences("p", MODE_PRIVATE);\n            String key = sp.getString("key", "");\n            String model = sp.getString("model", "grok-4");\n            if (model.isEmpty()) model = "grok-4";\n\n            int w = bmp.getWidth(), h = bmp.getHeight();\n            int max = 1100;\n            if (w > max) {\n                h = h * max / w; w = max;\n                bmp = Bitmap.createScaledBitmap(bmp, w, h, true);\n            }\n            ByteArrayOutputStream bo = new ByteArrayOutputStream();\n            bmp.compress(Bitmap.CompressFormat.JPEG, 80, bo);\n            String b64 = Base64.encodeToString(bo.toByteArray(), Base64.NO_WRAP);\n\n            JSONObject img = new JSONObject()\n                    .put("type", "image_url")\n                    .put("image_url", new JSONObject().put("url", "data:image/jpeg;base64," + b64));\n            JSONObject txt = new JSONObject()\n                    .put("type", "text")\n                    .put("text", "Посмотри на скриншот. Если на нём есть вопрос или задание - дай ответ. "\n                            + "Сначала коротко сам ответ, потом краткое пояснение. "\n                            + "Отвечай на том же языке, что и текст на экране. "\n                            + "Если вопроса нет - кратко опиши, что на экране.");\n            JSONObject msg = new JSONObject()\n                    .put("role", "user")\n                    .put("content", new JSONArray().put(img).put(txt));\n            JSONObject body = new JSONObject()\n                    .put("model", model)\n                    .put("messages", new JSONArray().put(msg));\n\n            HttpURLConnection c = (HttpURLConnection) new URL("https://api.x.ai/v1/chat/completions").openConnection();\n            c.setRequestMethod("POST");\n            c.setConnectTimeout(30000);\n            c.setReadTimeout(120000);\n            c.setDoOutput(true);\n            c.setRequestProperty("Content-Type", "application/json");\n            c.setRequestProperty("Authorization", "Bearer " + key);\n            OutputStream os = c.getOutputStream();\n            os.write(body.toString().getBytes("UTF-8"));\n            os.close();\n\n            int code = c.getResponseCode();\n            InputStream is = code >= 400 ? c.getErrorStream() : c.getInputStream();\n            ByteArrayOutputStream ro = new ByteArrayOutputStream();\n            byte[] buf = new byte[4096];\n            int n;\n            while ((n = is.read(buf)) > 0) ro.write(buf, 0, n);\n            String resp = ro.toString("UTF-8");\n\n            if (code >= 400) {\n                result = "Ошибка " + code + ":\\n" + resp;\n            } else {\n                result = new JSONObject(resp).getJSONArray("choices")\n                        .getJSONObject(0).getJSONObject("message").getString("content");\n            }\n        } catch (Exception e) {\n            result = "Ошибка: " + e;\n        }\n        final String out = result;\n        ui.post(new Runnable() {\n            public void run() {\n                busy = false;\n                showText(out);\n            }\n        });\n    }\n}\n'}
for path, text in FILES.items():
    d = os.path.dirname(path)
    if d:
        os.makedirs(d, exist_ok=True)
